{
    let seed: u8 = 0x08;
    let expected: [u8; 64] = [
        0x40, 0x00, 0x79, 0x08, 0xED, 0x13, 0x1B, 0x22, 0x57, 0x30, 0x37, 0x3E, 0x1B, 0x4C, 
        0x53, 0x5A, 0x1D, 0x6A, 0x6F, 0x76, 0x1A, 0x84, 0x8B, 0x92, 0xDB, 0xA1, 0xA7, 0xAE, 
        0x81, 0xBC, 0xC3, 0xCA, 0xB1, 0xDB, 0xDF, 0xE6, 0xBE, 0xF4, 0xFB, 0x02, 0x7B, 0x10, 
        0x17, 0x1E, 0x1D, 0x2C, 0x33, 0x3A, 0xED, 0x49, 0x4F, 0x56, 0xF3, 0x63, 0x6B, 0x72, 
        0x65, 0x82, 0x87, 0x8E, 0x7A, 0x9C, 0xA3, 0xAA, 
    ];
    let mut buf = sample_frame(64);
    encrypt(&mut buf, seed);
    assert_eq!(buf[..], expected[..], "encrypt diverge do C# original");
    let mut dec = expected.to_vec();
    assert!(decrypt(&mut dec), "checksum do vetor C# nao validou");
    assert_eq!(dec[4..], sample_frame(64)[4..], "decrypt diverge do C# original");
}
